          <JxSelectTrigger id="profile-language">
            <JxSelectValue placeholder="Выберите язык" />
          </JxSelectTrigger>
          <JxSelectContent>
            <JxSelectItem value="ru">Русский</JxSelectItem>
            <JxSelectItem value="en">Английский</JxSelectItem>
          </JxSelectContent>
        </JxSelect>
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <JxLabel htmlFor="profile-email-notifications">Уведомления на почту</JxLabel>
        <JxSwitch
          id="profile-email-notifications"
          value={emailNotifications}
          onValueChange={setEmailNotifications}
        />
      </div>

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

